CREATE OR REPLACE FUNCTION check_resolved_trigger_fn()
RETURNS TRIGGER AS $$
DECLARE
    iii numeric;
BEGIN
    -- Only check when res_state is being set to 'Resolved'
    IF NEW."enf_actions"->>'res_state' = 'Resolved' THEN
        -- Calculate Investigation Intensity Index via market_conditions join to reg_compliance
        SELECT (0.6 * rc.behav_score + 0.4 * rc.net_score)::numeric INTO iii
        FROM enforcement_actions e
        JOIN market_conditions m ON e."REC_ENF" = m."REC_PIN"
        JOIN reg_compliance rc ON rc."REC_COMP" = m."REC_PIN"
        WHERE e."REC_ENF" = OLD."REC_ENF";

        -- Block if III exceeds threshold
        IF iii > 150 THEN
            RAISE EXCEPTION 'Cannot resolve case % - Investigation Intensity Index (%). Case requires further review.', NEW."REC_ENF", iii;
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

