DECLARE v_iii numeric; BEGIN SELECT (0.6 * rc.behav_score + 0.4 * rc.net_score)::numeric INTO v_iii FROM market_conditions m JOIN reg_compliance rc ON rc.REC_COMP = m.REC_PIN WHERE m.REC_PIN = NEW.REC_ENF; IF v_iii > 150 THEN RAISE EXCEPTION 'Cannot resolve case % - Investigation Intensity Index %. Case requires further review.', NEW.REC_ENF, v_iii; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql; CREATE TRIGGER trg_check BEFORE UPDATE ON enforcement_actions FOR EACH ROW EXECUTE FUNCTION check_resolved();
